class Database {
  // 1. Static property to hold the single instance
  private static instance: Database;

  // 2. PRIVATE constructor prevents 'new Database()'
  private constructor() {
    console.log("Initializing Database Connection...");
  }

  // 3. Static method controls access to the instance
  public static getInstance(): Database {
    if (!Database.instance) {
      Database.instance = new Database();
    }
    return Database.instance;
  }

  public query(sql: string) {
    console.log(`Executing: ${sql}`);
  }
}

// ERROR: Constructor of class 'Database' is private
// const db = new Database(); 

const db1 = Database.getInstance(); // Prints: Initializing Database...
const db2 = Database.getInstance(); // Doesn't print anything!

console.log(db1 === db2); // true (Exact same object in memory)
